        uint256 finalPercentage = (attackerFinalBalance * 1e18) / finalTotalSupply;

        // Assert that attacker's share of supply increased
        assertGt(finalPercentage, initialPercentage, "Attacker's share of total supply should increase");

        // Also check that total supply actually decreased
        assertLt(finalTotalSupply, initialTotalSupply, "Total supply should decrease after burning");
    }




    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
